use std::fmt::Write;

use super::layout::{Field, FieldKind, Offsets};

/// Render the C++ header corresponding to finalized FX layout metadata.
pub fn render(fields: &[Field], offsets: &Offsets) -> String {
    let mut output = String::new();

    output.push_str(concat!(
        "#pragma once\n\n",
        "/**** FX data header generated by cgfx-tools ****/\n\n",
        "using uint24_t = __uint24;\n\n",
        "// Initialize FX hardware using  FX::begin(FX_DATA_PAGE); in the setup() function.\n\n",
    ));
    let _ = writeln!(
        output,
        "constexpr uint16_t FX_DATA_PAGE  = 0x{:04x};",
        offsets.data_page
    );
    let _ = writeln!(
        output,
        "constexpr uint24_t FX_DATA_BYTES = {};",
        offsets.data_len
    );

    if let Some(save_page) = offsets.save_page {
        output.push('\n');
        let _ = writeln!(
            output,
            "constexpr uint16_t FX_SAVE_PAGE  = 0x{save_page:04X};"
        );
        let _ = writeln!(
            output,
            "constexpr uint24_t FX_SAVE_BYTES = {};",
            offsets.save_len
        );

        let save_fields: Vec<_> = fields.iter().filter(|field| field.in_save).collect();
        if !save_fields.is_empty() {
            let _ = writeln!(output, "\n// FX save section offsets");
            for field in save_fields {
                let _ = writeln!(
                    output,
                    "constexpr uint24_t {} = 0x{:06X};",
                    field.name, field.addr
                );
            }
        }
    }
    output.push('\n');

    let mut current_namespace = Vec::new();
    for field in fields.iter().filter(|field| !field.in_save) {
        let namespace = field
            .namespace
            .as_deref()
            .map_or_else(Vec::new, |path| path.split("::").collect());
        transition_namespace(&mut output, &mut current_namespace, &namespace);

        let indent = "  ".repeat(current_namespace.len());
        match &field.kind {
            FieldKind::Bytes => {
                let _ = writeln!(
                    output,
                    "{indent}constexpr uint24_t {} = 0x{:06X};",
                    field.name, field.addr
                );
            }
            FieldKind::Image {
                frames,
                width,
                height,
            } => {
                let _ = writeln!(
                    output,
                    "{indent}constexpr uint24_t {} = 0x{:06X};",
                    field.name, field.addr
                );
                let _ = writeln!(
                    output,
                    "{indent}constexpr uint16_t {}Width  = {};",
                    field.name, width
                );
                let _ = writeln!(
                    output,
                    "{indent}constexpr uint16_t {}Height = {};",
                    field.name, height
                );
                let _ = writeln!(
                    output,
                    "{indent}constexpr uint8_t  {}Frames = {};",
                    field.name, frames
                );
                output.push('\n');
            }
        }
    }

    transition_namespace(&mut output, &mut current_namespace, &[]);

    output
}

fn transition_namespace<'a>(output: &mut String, current: &mut Vec<&'a str>, next: &[&'a str]) {
    let common = current
        .iter()
        .zip(next)
        .take_while(|(left, right)| left == right)
        .count();
    let closed_namespace = common < current.len();
    for _ in common..current.len() {
        output.push_str("}\n");
    }
    current.truncate(common);
    if closed_namespace {
        output.push('\n');
    }
    for component in &next[common..] {
        let _ = writeln!(output, "namespace {component}");
        output.push_str("{\n");
        current.push(component);
    }
}
